-- docQA schema v1 (ADR 0006). Replaces the M0 init migration.
--
-- Layout of this file:
--   1. Roles (created if missing, NOLOGIN; infra grants LOGIN and passwords)
--   2. Helper functions used by column defaults and RLS policies
--   3. Tables, keys and indexes (generated by Prisma from schema.prisma)
--   4. Objects Prisma cannot express: partitioning, CHECK constraints, partial unique
--      indexes, triggers, partitions, ACL and admission functions, RLS, grants
--
-- Running it needs a superuser, or a role that can create roles with BYPASSRLS and is a
-- member of docqa_admission (for ALTER FUNCTION ... OWNER TO docqa_admission).

-- ---------------------------------------------------------------------------
-- 1. Roles. No application role bypasses RLS. docqa_admission only owns admit_jobs().
-- ---------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docqa_owner') THEN
        CREATE ROLE docqa_owner NOLOGIN BYPASSRLS;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docqa_backend') THEN
        CREATE ROLE docqa_backend NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docqa_worker') THEN
        CREATE ROLE docqa_worker NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docqa_ai') THEN
        CREATE ROLE docqa_ai NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docqa_admission') THEN
        CREATE ROLE docqa_admission NOLOGIN BYPASSRLS;
    END IF;
END
$$;

-- ---------------------------------------------------------------------------
-- 2. Helper functions
-- ---------------------------------------------------------------------------

-- UUIDv7 (RFC 9562): 48-bit Unix ms timestamp, version 7, random rest. Same name and
-- signature as the Postgres 18 built-in, so it can be dropped after that upgrade.
CREATE FUNCTION uuidv7() RETURNS uuid
    LANGUAGE plpgsql VOLATILE PARALLEL SAFE
AS $$
DECLARE
    v_ms    bigint := floor(extract(epoch FROM clock_timestamp()) * 1000);
    v_bytes bytea  := uuid_send(gen_random_uuid());
BEGIN
    v_bytes := overlay(v_bytes PLACING substring(int8send(v_ms) FROM 3) FROM 1 FOR 6);
    v_bytes := set_byte(v_bytes, 6, (get_byte(v_bytes, 6) & 15) | 112);
    RETURN encode(v_bytes, 'hex')::uuid;
END
$$;

-- The tenant of the current transaction, set with set_config('app.tenant_id', ..., true).
CREATE FUNCTION app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
AS $$
    SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid
$$;

-- Keeps updated_at current for every writer, not only Prisma (@updatedAt).
CREATE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END
$$;

-- Monthly partitions of usage_events and audit_log live in their own schema, so Prisma
-- (which reads only "public") never sees them.
CREATE SCHEMA partitions;

