-- Duplicate rule (ADR 0006, 6A): one live copy of each file per tenant. Deleted, superseded,
-- failed and rejected versions don't count, so retries and re-uploads after delete work.
CREATE UNIQUE INDEX "uq_document_versions_tenant_id_content_hash"
    ON "document_versions" ("tenant_id", "content_hash")
    WHERE "deleted_at" IS NULL AND "superseded_at" IS NULL
      AND "status" NOT IN ('failed', 'rejected');

-- At most one active search index.
CREATE UNIQUE INDEX "uq_search_indexes_status_active"
    ON "search_indexes" ("status") WHERE "status" = 'active';

-- At most one tenant-wide grant per document (user and group grants have plain uniques).
CREATE UNIQUE INDEX "uq_document_acls_tenant_id_document_id_tenant_grant"
    ON "document_acls" ("tenant_id", "document_id") WHERE "principal_type" = 'tenant';

