-- The audit log is append-only. Retention drops whole monthly partitions (DDL, not DELETE).
CREATE FUNCTION audit_log_append_only() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;
CREATE TRIGGER "trg_audit_log_append_only" BEFORE UPDATE OR DELETE ON "audit_log"
    FOR EACH ROW EXECUTE FUNCTION audit_log_append_only();

-- ---------------------------------------------------------------------------
-- 4d. Monthly partitions for usage_events and audit_log
-- ---------------------------------------------------------------------------

-- Creates the current month plus p_months_ahead months (UTC). Run on a schedule as the
-- schema owner. A default partition catches stray rows.
CREATE FUNCTION ensure_partitions(p_months_ahead integer DEFAULT 3) RETURNS void
    LANGUAGE plpgsql
AS $$
DECLARE
    v_table text;
    v_month timestamp;
    v_i     integer;
BEGIN
    FOREACH v_table IN ARRAY ARRAY['usage_events', 'audit_log'] LOOP
        FOR v_i IN 0..p_months_ahead LOOP
            v_month := date_trunc('month', now() AT TIME ZONE 'UTC') + make_interval(months => v_i);
            EXECUTE format(
                'CREATE TABLE IF NOT EXISTS partitions.%I PARTITION OF public.%I '
                'FOR VALUES FROM (%L) TO (%L)',
                v_table || '_' || to_char(v_month, 'YYYY_MM'),
                v_table,
                v_month AT TIME ZONE 'UTC',
                (v_month + interval '1 month') AT TIME ZONE 'UTC'
            );
        END LOOP;
    END LOOP;
END
$$;
REVOKE ALL ON FUNCTION ensure_partitions(integer) FROM PUBLIC;

CREATE TABLE partitions.usage_events_default PARTITION OF "usage_events" DEFAULT;
CREATE TABLE partitions.audit_log_default PARTITION OF "audit_log" DEFAULT;
SELECT ensure_partitions(3);

-- ---------------------------------------------------------------------------
-- 4e. Access and admission functions
-- ---------------------------------------------------------------------------

-- The one ACL rule (ADR 0006, section 5): own grants, plus grants to the user's groups,
-- plus tenant-wide grants. Tenant admins see every document. Deactivated users see none.
-- SECURITY INVOKER, so RLS limits it to the current tenant.
CREATE FUNCTION accessible_document_ids(
    p_user_id uuid,
    p_min_permission text DEFAULT 'read',
    p_document_ids uuid[] DEFAULT NULL
) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY INVOKER
AS $$
    WITH me AS (
        SELECT u.id, u.role FROM users u
        WHERE u.id = p_user_id AND u.deactivated_at IS NULL
    ), need AS (
        SELECT array_position(ARRAY['read', 'write', 'admin'], p_min_permission) AS level
    )
    SELECT d.id
    FROM documents d CROSS JOIN me CROSS JOIN need
    WHERE d.deleted_at IS NULL
      AND (p_document_ids IS NULL OR d.id = ANY (p_document_ids))
      AND (
          me.role = 'admin'
          OR EXISTS (
              SELECT 1 FROM document_acls a
              WHERE a.tenant_id = d.tenant_id
                AND a.document_id = d.id
                AND array_position(ARRAY['read', 'write', 'admin'], a.permission) >= need.level
                AND (
                    a.principal_type = 'tenant'
                    OR a.user_id = me.id
                    OR a.group_id IN (
                        SELECT gm.group_id FROM group_memberships gm WHERE gm.user_id = me.id
                    )
                )
          )
      )
$$;

-- Fair job admission (ADR 0006, 6D): claims queued jobs round-robin by tenant, within each
-- tenant's running-job limit and a global limit, and marks them running. The single path
-- that reads across tenants: owned by docqa_admission (BYPASSRLS, rights on jobs only) and
-- callable only by docqa_worker. Returns ids only.
CREATE FUNCTION admit_jobs(p_per_tenant integer, p_global integer)
    RETURNS TABLE (job_id uuid, job_tenant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path = public, pg_temp
AS $$
DECLARE
    v_slots integer;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtext('docqa.admit_jobs'));
    SELECT p_global - count(*) INTO v_slots FROM jobs WHERE status = 'running';
    IF v_slots <= 0 THEN
        RETURN;
    END IF;
    RETURN QUERY
    WITH running AS (
        SELECT j.tenant_id, count(*) AS n FROM jobs j WHERE j.status = 'running' GROUP BY j.tenant_id
    ), ranked AS (
        SELECT j.id, j.priority, j.created_at,
               row_number() OVER (PARTITION BY j.tenant_id ORDER BY j.priority, j.created_at) AS rn,
               COALESCE(s.max_running_jobs, p_per_tenant) - COALESCE(r.n, 0) AS free
        FROM jobs j
        JOIN tenants t ON t.id = j.tenant_id AND t.status <> 'suspended'
        LEFT JOIN running r ON r.tenant_id = j.tenant_id
        LEFT JOIN tenant_settings s ON s.tenant_id = j.tenant_id
        WHERE j.status = 'queued'
    ), picked AS (
        SELECT k.id FROM ranked k WHERE k.rn <= k.free
        ORDER BY k.rn, k.priority, k.created_at
        LIMIT v_slots
    ), locked AS (
        SELECT j.id FROM jobs j WHERE j.id IN (SELECT p.id FROM picked p)
        FOR UPDATE SKIP LOCKED
    )
    UPDATE jobs j SET status = 'running', admitted_at = now()
    FROM locked l WHERE j.id = l.id
    RETURNING j.id, j.tenant_id;
END
$$;

-- ---------------------------------------------------------------------------
-- 4f. Row-level security
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    v_table text;
BEGIN
    FOREACH v_table IN ARRAY ARRAY[
        'users', 'groups', 'group_memberships', 'documents', 'document_versions',
        'document_acls', 'upload_sessions', 'chunks', 'document_version_indexes', 'jobs',
        'conversations', 'queries', 'answers', 'citations', 'feedback', 'usage_events',
        'usage_daily'
    ] LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', v_table);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', v_table);
        EXECUTE format(
            'CREATE POLICY tenant_isolation ON %I '
            'USING (tenant_id = app_current_tenant()) '
            'WITH CHECK (tenant_id = app_current_tenant())',
            v_table
        );
    END LOOP;
END
$$;

-- audit_log: a tenant reads and writes its own rows; null-tenant (platform) rows only when
-- the backend has verified a platform admin. No UPDATE or DELETE policy exists.
ALTER TABLE "audit_log" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_log" FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON "audit_log" FOR SELECT USING (
    tenant_id = app_current_tenant()
    OR (tenant_id IS NULL AND current_setting('app.platform_admin', true) = 'on')
);
CREATE POLICY audit_insert ON "audit_log" FOR INSERT WITH CHECK (
    tenant_id = app_current_tenant()
    OR (tenant_id IS NULL AND current_setting('app.platform_admin', true) = 'on')
);

-- ---------------------------------------------------------------------------
-- 4g. Grants and per-role settings. New tables must be added here in their own migration.
-- ---------------------------------------------------------------------------
GRANT USAGE ON SCHEMA public TO docqa_backend, docqa_worker, docqa_ai, docqa_admission;

-- Backend: the public API. Everything except changing logs.
GRANT SELECT, INSERT, UPDATE, DELETE ON
    "tenants", "tenant_settings", "search_indexes", "model_prices", "users", "groups",
    "group_memberships", "document_acls", "documents", "document_versions", "upload_sessions",
    "chunks", "document_version_indexes", "jobs", "conversations", "queries", "answers",
    "citations", "feedback", "usage_daily"
    TO docqa_backend;
GRANT SELECT, INSERT ON "usage_events", "audit_log" TO docqa_backend;

-- Worker: ingestion, jobs, retention and tenant purge. Reads everything it needs.
GRANT SELECT ON
    "tenants", "tenant_settings", "search_indexes", "model_prices", "users", "groups",
    "group_memberships", "document_acls", "documents", "document_versions", "upload_sessions",
    "chunks", "document_version_indexes", "jobs", "conversations", "queries", "answers",
    "citations", "feedback", "usage_events", "usage_daily", "audit_log"
    TO docqa_worker;
GRANT INSERT, UPDATE, DELETE ON
    "documents", "document_versions", "upload_sessions", "chunks", "document_version_indexes",
    "jobs", "search_indexes", "usage_daily"
    TO docqa_worker;
GRANT UPDATE, DELETE ON "tenants" TO docqa_worker;
GRANT DELETE ON "conversations", "queries" TO docqa_worker;
GRANT INSERT ON "usage_events", "audit_log" TO docqa_worker;

-- ai-api: reads what retrieval and the ACL re-check need; writes answers and usage.
GRANT SELECT ON
    "tenants", "tenant_settings", "search_indexes", "users", "groups", "group_memberships",
    "document_acls", "documents", "document_versions", "chunks", "conversations", "queries",
    "answers", "citations"
    TO docqa_ai;
GRANT INSERT, UPDATE ON "queries" TO docqa_ai;
GRANT INSERT ON "answers", "citations", "usage_events" TO docqa_ai;

-- Admission: only what admit_jobs() touches.
GRANT SELECT, UPDATE ON "jobs" TO docqa_admission;
GRANT SELECT ON "tenants", "tenant_settings" TO docqa_admission;

ALTER FUNCTION admit_jobs(integer, integer) OWNER TO docqa_admission;
REVOKE ALL ON FUNCTION admit_jobs(integer, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admit_jobs(integer, integer) TO docqa_worker;

ALTER ROLE docqa_backend SET statement_timeout = '5s';
ALTER ROLE docqa_ai SET statement_timeout = '3s';
ALTER ROLE docqa_worker SET statement_timeout = '60s';
